import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"37、【家人】 离下巽上","description":"周易口诀义 - 37、【家人】 离下巽上","frontmatter":{"title":"37、【家人】 离下巽上","description":"周易口诀义 - 37、【家人】 离下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/039.md","filePath":"zh/classics/koujueyi/039.md"}'),r={name:"zh/classics/koujueyi/039.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_37、【家人】-离下巽上" tabindex="-1">37、【家人】 离下巽上 <a class="header-anchor" href="#_37、【家人】-离下巽上" aria-label="Permalink to “37、【家人】 离下巽上”">​</a></h1><p>彖曰：家人，女正位乎内，男正位乎外。男女正，天地之大义也。家人有严君焉，父母之谓也。父父、子子、兄兄、弟弟、夫夫、妇妇，而家道正，正家而天下定矣。象曰：风自火出，家人。君子以言有物而行有恒。</p><p>初九：闲有家，悔亡。</p><p>象曰：「闲有家」，志未变也。</p><p>六二：无攸遂，在中馈，贞吉。</p><p>象曰：六二之吉，顺以巽也。</p><p>九三：家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。</p><p>象曰：「家人嗃嗃」，未失也；「妇子嘻嘻」，失家节也。</p><p>六四，富家，大吉。</p><p>象曰：「富家大吉」，顺在位也。</p><p>九五，王假有家，勿恤，吉。</p><p>象曰：「王假有家」，交相爱也。</p><p>上九，有孚威如，终吉。</p><p>象曰：「威如」之吉，反身之谓也。</p><p>解读</p><p>「家人，利女贞」者，家人谓室家之人，故孔氏云「明家内之道，正一家之人」是也。治家之道，非丈夫独正，内在女子，故曰「利女贞」也。</p><p>象曰「风自火出，家人」者，离火巽风。夫火之为体，因风而生，火既炎盛，还复生风，风火相成，似夫妇成家之义也。「君子以言有物而行有恒」者，「物」，事也，君子所言，皆须有事，论语典实，事不虚妄矣。所行德行，不亏于常，故曰「行有恒」也。</p><p>初九「闲有家，悔亡」者，闲，防也；夫治家之道，必须先以防虑，不令渎乱，若候渎乱之后方始治之，即忧悔生矣。今治家之初，便能防闲，悔必亡矣。</p><p>六二「无攸遂，在中馈，贞吉」者，以柔处中，以阴应阳，正夫妇之义也。妇人职务，但事供给馈食祭祀而已，全非遂志之人，故曰「无攸遂，在中馈，贞吉」也。</p><p>九三，家人嗃嗃，悔厉，吉。「妇子嘻嘻，终吝」者，嗃嗃，严整之貌；嘻嘻，喜笑之声；悔，过也；九三处一卦之上，为一家之长，理家之道，必须严整，直是过于猛难，虽似危酷，后乃获吉，故曰「家人嗃嗃，悔厉，吉」。若从妇人笑语，不制不节，终致悔吝，故曰「嘻嘻，终吝」也。</p><p>六四「富家，大吉」者，富，谓禄位昌盛之名也；六四柔巽之质，上奉于君而得其位，即是禄位昌盛而富其家，长保安吉之大也。</p><p>九五「王假有家，勿恤，吉」者，假，至也；体刚居巽而得尊位，能以巽顺接待于下，至于天下尽有其家，莫不归王之化，故不假忧恤，自然获吉。先儒云：犹如舜能治家，处于妫涒，即是归让至焉。</p><p>上九「有孚，威如，终吉」者，处家人之极，家道大成也。刑于寡妻，义彰于外，信被天下，故曰「有孚」。威及遐迩，故曰「威如」。威信并至，敬义交接，终保其吉，故曰「终吉」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
